using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;

static class Tests {
    static void Assert(bool condition,string message){if(!condition)throw new Exception(message);}
    public static int Unit(){try{
        using(var s=new MemoryStream(System.Text.Encoding.ASCII.GetBytes("123456789")))Assert(App.CrcStream(s,CancellationToken.None)==0xCBF43926,"CRC vector");
        Assert(App.Inside(@"C:\a\b",@"C:\a")&&!App.Inside(@"C:\abc",@"C:\a"),"Path boundaries");
        Assert(JobPaths.FolderDestination(@"C:\Source\Photos",@"D:\Backup",true)==@"D:\Backup\Photos","Preserve source folder name");
        Assert(JobPaths.FolderDestination(@"C:\Source\Photos",@"D:\Backup\Photos",true)==@"D:\Backup\Photos","Reuse matching destination name");
        Assert(JobPaths.FolderDestination(@"C:\Source\Photos",@"D:\Backup",false)==@"D:\Backup","Contents-only destination");
        string pickerTest=Path.Combine(Path.GetTempPath(),"Evacopy-picker-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(pickerTest);string sample=Path.Combine(pickerTest,"file; ü.txt");File.WriteAllText(sample,"picker");
        try{Assert(PickerPaths.ExistingDirectory(pickerTest)==pickerTest,"Picker opens displayed folder");Assert(PickerPaths.ExistingDirectory(sample)==pickerTest,"File picker starts in selected file parent");Assert(PickerPaths.ExistingDirectory(Path.Combine(pickerTest,"missing","nested"))==pickerTest,"Missing destination starts in closest existing parent");Assert(String.Equals(FolderPicker.CheckInitialFolder(sample),pickerTest,StringComparison.OrdinalIgnoreCase),"Native Explorer dialog opens requested path");}finally{File.Delete(sample);Directory.Delete(pickerTest);}
        var window=(Window)XamlReader.Parse(App.Layout);
        using(var stream=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("Evacopy.png"))((Image)window.FindName("BrandIcon")).Source=System.Windows.Media.Imaging.BitmapFrame.Create(stream);
        var grid=(Grid)window.Content;grid.Measure(new Size(571,391));grid.Arrange(new Rect(0,0,571,391));grid.UpdateLayout();
        var start=(Button)window.FindName("Start");Assert(start.ActualHeight>20&&start.TranslatePoint(new Point(0,start.ActualHeight),grid).Y<=grid.ActualHeight,"New job controls fit reference size");Assert(window.Width==577&&window.Height==420,"Reference window dimensions");
        foreach(var name in new[]{"Remove","LaunchAtLogin","EnableHotkey","IncludeFolder","VerifyCrc"})Assert(((CheckBox)window.FindName(name)).Foreground.ToString()=="#FFFFFFFF","Checkbox foreground: "+name);
        Assert(((CheckBox)window.FindName("IncludeFolder")).IsChecked==true,"Folder-copy option defaults on");
        var browse=(Button)window.FindName("SourceBrowse");Assert(browse.Content.ToString()=="Browse…"&&browse.ContextMenu.Items.Count==2,"One source Browse button with two choices");Assert(((MenuItem)browse.ContextMenu.Items[0]).Header.ToString()=="Folder…"&&((MenuItem)browse.ContextMenu.Items[1]).Header.ToString()=="Files…","Folder and files dropdown choices");
        Assert(((CheckBox)window.FindName("VerifyCrc")).IsChecked==false&&!new JobSpec().VerifyCrc,"CRC defaults off in UI and job configuration");
        Assert(window.Title=="Evacopy","Brand title");
        using(var stream=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("Evacopy.ico"))Assert(stream!=null&&stream.Length>1000,"Embedded icon");
        var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap(571,391,96,96,System.Windows.Media.PixelFormats.Pbgra32);var background=new System.Windows.Media.DrawingVisual();using(var drawing=background.RenderOpen())drawing.DrawRectangle(new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(5,17,37)),null,new Rect(0,0,571,391));bitmap.Render(background);bitmap.Render(grid);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Evacopy-preview.png")))encoder.Save(file);
        return 0;
    }catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"unit-test-error.txt"),ex.ToString());return 1;}}
    static Reply Send(Request request){var r=Store.Send(request);if(r.Error!=null)throw new Exception(r.Error);return r;}
    static JobSpec Spec(string source,string target,bool delete){return new JobSpec{Sources=new[]{source},Destination=target,DeleteSource=delete,VerifyCrc=true,Threads=8,Priority="Normal"};}
    static JobState WaitForSuccess(string id){var deadline=DateTime.UtcNow.AddSeconds(30);while(DateTime.UtcNow<deadline){var state=Send(new Request{Command="list"}).Jobs.Single(s=>s.Id==id);if(state.Finished){Assert(state.Successful,"Job failed: "+state.Error);return state;}Thread.Sleep(100);}throw new Exception("Job timed out: "+id);}
    static bool Gone(int pid){try{using(var process=System.Diagnostics.Process.GetProcessById(pid))return process.HasExited;}catch(ArgumentException){return true;}}
    public static int Integration(){string root=Path.GetDirectoryName(Store.Root);try{
        Directory.CreateDirectory(root);string a=Path.Combine(root,"source A"),b=Path.Combine(root,"source B"),da=Path.Combine(root,"target A"),db=Path.Combine(root,"target B");
        foreach(var dir in new[]{a,b}){Directory.CreateDirectory(Path.Combine(dir,"nested","empty"));File.WriteAllText(Path.Combine(dir,"nested","unicode ü.txt"),"Evacopy integrity check");File.WriteAllBytes(Path.Combine(dir,"empty.file"),new byte[0]);using(var f=File.Create(Path.Combine(dir,"payload.bin"))){var data=new byte[1024*1024];new Random(123).NextBytes(data);for(int i=0;i<32;i++)f.Write(data,0,data.Length);}}
        Store.EnsureService();string first=Send(new Request{Command="submit",Job=Spec(a,da,true)}).Id;
        var conflict=Store.Send(new Request{Command="submit",Job=Spec(b,da,false)});Assert(conflict.Error!=null,"Overlapping job rejected");
        string second=Send(new Request{Command="submit",Job=Spec(b,db,false)}).Id;bool concurrent=false,copySeen=false,restarted=false;JobState[] all=null;
        var deadline=DateTime.UtcNow.AddSeconds(90);
        while(DateTime.UtcNow<deadline){all=Send(new Request{Command="list"}).Jobs;var one=all.Single(s=>s.Id==first);var two=all.Single(s=>s.Id==second);if(one.WorkerPid>0&&two.WorkerPid>0){Assert(one.WorkerPid!=two.WorkerPid,"Independent worker PIDs");Assert(one.WorkerPid!=System.Diagnostics.Process.GetCurrentProcess().Id,"Worker separate from client");if(!one.Finished&&!two.Finished)concurrent=true;}copySeen|=all.Any(s=>s.CopyPid>0);if(concurrent&&copySeen&&!restarted){int service=Send(new Request{Command="ping"}).ServicePid;using(var broker=System.Diagnostics.Process.GetProcessById(service)){broker.Kill();broker.WaitForExit();}Store.EnsureService();restarted=true;}if(one.Finished&&two.Finished)break;Thread.Sleep(100);}
        Assert(all!=null&&all.Where(s=>s.Id==first||s.Id==second).All(s=>s.Finished&&s.Successful),"Both copy/CRC jobs completed: "+Store.Json(all));Assert(concurrent,"Jobs overlapped");Assert(restarted,"Supervisor restart recovery");Assert(copySeen,"Separate Robocopy PID observed");Assert(!Directory.Exists(a),"Verified move removed source root");Assert(File.Exists(Path.Combine(b,"payload.bin")),"Copy preserved source");Assert(Directory.Exists(Path.Combine(da,"nested","empty")),"Empty directory copied");Assert(App.Crc(Path.Combine(da,"payload.bin"),CancellationToken.None)==App.Crc(Path.Combine(db,"payload.bin"),CancellationToken.None),"Copied content CRC");
        string third=Send(new Request{Command="submit",Job=Spec(b,Path.Combine(root,"cancel target"),true)}).Id;Send(new Request{Command="cancel",Id=third});JobState cancelled=null;deadline=DateTime.UtcNow.AddSeconds(30);while(DateTime.UtcNow<deadline){cancelled=Send(new Request{Command="list"}).Jobs.Single(s=>s.Id==third);if(cancelled.Finished)break;Thread.Sleep(100);}Assert(cancelled!=null&&cancelled.Phase=="Cancelled","Cancellation state");Assert(File.Exists(Path.Combine(b,"payload.bin")),"Cancellation retained source");
        string album=Path.Combine(root,"Album ü"),parent=Path.Combine(root,"folder targets");Directory.CreateDirectory(Path.Combine(album,"nested","empty"));File.WriteAllText(Path.Combine(album,"nested","photo.txt"),"folder copy verification");
        var preserve=Spec(album,parent,false);preserve.IncludeSourceFolder=true;string folderJob=Send(new Request{Command="submit",Job=preserve}).Id;WaitForSuccess(folderJob);
        string albumTarget=Path.Combine(parent,"Album ü");Assert(File.Exists(Path.Combine(albumTarget,"nested","photo.txt")),"Source folder created inside destination");Assert(!Directory.Exists(Path.Combine(parent,"nested")),"No loose source contents in destination parent");Assert(Directory.Exists(Path.Combine(albumTarget,"nested","empty")),"Nested empty folder retained");
        File.WriteAllText(Path.Combine(albumTarget,"keep.txt"),"destination-only file");preserve=Spec(album,albumTarget,false);preserve.IncludeSourceFolder=true;WaitForSuccess(Send(new Request{Command="submit",Job=preserve}).Id);Assert(!Directory.Exists(Path.Combine(albumTarget,"Album ü")),"Matching destination not double nested");Assert(File.Exists(Path.Combine(albumTarget,"keep.txt")),"Destination-only file retained");
        string moving=Path.Combine(root,"Move folder");Directory.CreateDirectory(Path.Combine(moving,"empty"));File.WriteAllText(Path.Combine(moving,"verified.txt"),"verified move");var move=Spec(moving,parent,true);move.IncludeSourceFolder=true;move.VerifyCrc=false;var moved=WaitForSuccess(Send(new Request{Command="submit",Job=move}).Id);Assert(moved.CrcBytesRead>0,"Source deletion automatically requires CRC");Assert(!Directory.Exists(moving)&&File.Exists(Path.Combine(parent,"Move folder","verified.txt")),"Folder-preserving move verified and cleaned source");
        var fast=Spec(b,Path.Combine(root,"fast target"),false);fast.VerifyCrc=false;var fastState=WaitForSuccess(Send(new Request{Command="submit",Job=fast}).Id);Assert(fastState.CrcBytesRead==0&&fastState.Phase=="Completed · CRC off","Fast folder copy performs no CRC data reads");Assert(App.Crc(Path.Combine(fast.Destination,"payload.bin"),CancellationToken.None)==App.Crc(Path.Combine(b,"payload.bin"),CancellationToken.None),"Fast copy content matches");
        string files=Path.Combine(root,"selected files");Directory.CreateDirectory(files);File.WriteAllText(Path.Combine(files,"one.txt"),"one");File.WriteAllText(Path.Combine(files,"two.txt"),"two");File.WriteAllText(Path.Combine(files,"not selected.txt"),"exclude");var selectedFiles=new JobSpec{Sources=new[]{Path.Combine(files,"one.txt"),Path.Combine(files,"two.txt")},Destination=Path.Combine(root,"selected target"),Threads=8,Priority="Normal"};var fileState=WaitForSuccess(Send(new Request{Command="submit",Job=selectedFiles}).Id);Assert(fileState.CrcBytesRead==0&&File.ReadAllText(Path.Combine(selectedFiles.Destination,"one.txt"))=="one"&&File.ReadAllText(Path.Combine(selectedFiles.Destination,"two.txt"))=="two"&&!File.Exists(Path.Combine(selectedFiles.Destination,"not selected.txt")),"Fast batched selection copies only selected files");
        selectedFiles.VerifyCrc=true;var checkedFiles=WaitForSuccess(Send(new Request{Command="submit",Job=selectedFiles}).Id);Assert(checkedFiles.CrcBytesRead>0&&checkedFiles.Phase=="Completed · CRC verified","Optional CRC performs verification");
        int idleService=Send(new Request{Command="ping"}).ServicePid;Store.StopAll();Assert(Gone(idleService),"Exit stops idle service");
        Store.EnsureService();int activeService=Send(new Request{Command="ping"}).ServicePid;string exitJob=Send(new Request{Command="submit",Job=Spec(b,Path.Combine(root,"exit target"),false)}).Id;JobState active=null;deadline=DateTime.UtcNow.AddSeconds(30);while(DateTime.UtcNow<deadline){active=Send(new Request{Command="list"}).Jobs.Single(s=>s.Id==exitJob);if(active.CopyPid>0)break;Assert(!active.Finished,"Exit test reached an active copy");Thread.Sleep(25);}Assert(active!=null&&active.CopyPid>0,"Active copy PID captured for Exit");Store.StopAll();Assert(Gone(activeService)&&Gone(active.WorkerPid)&&Gone(active.CopyPid),"Exit stops service, worker and Robocopy");Assert(File.Exists(Path.Combine(b,"payload.bin")),"Exit preserves source");
        File.WriteAllText(Path.Combine(root,"RESULT.txt"),"PASS: concurrent workers, separate Robocopy processes, overlap rejection, supervisor restart recovery, CRC verification, verified move cleanup, folder-copy modes, optional CRC and zero-CRC fast mode, batched file selections, Unicode paths, cancellation, idle exit and active exit without leftover processes.");return 0;
    }catch(Exception ex){Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"ERROR.txt"),ex.ToString());try{Store.Send(new Request{Command="shutdown"});}catch{}return 1;}}
}
